# Rebuilds churn.ipynb and README.md so the forward-looking model is the main model comparison.
import json, sys
nb = json.load(open("churn.ipynb"))
def L(t):
    x = t.split("\n"); return [l + "\n" for l in x[:-1]] + [x[-1]]
def src(c): return "".join(c["source"])
cells = nb["cells"]
if any("Step 2: The Prediction Problem (Forward-Looking Design)" in src(c) for c in cells):
    sys.exit("Already applied - nothing changed.")
load = [i for i, c in enumerate(cells) if 'pd.read_csv("cleaned_retail.csv")' in src(c) or "cleaned_retail.csv" in src(c)]
assert load, "data-loading cell not found"
k = load[0] + 1
old = [c for c in cells[k:] if "Step 13: Forward-Looking Validation" not in src(c) and "Forward-looking validation: build features only from data BEFORE" not in src(c)
       and "Step 14: Four-Model Comparison" not in src(c) and "# Step 14: compare all four algorithms" not in src(c)]
CODE = {'c1': 'import numpy as np\nfrom sklearn.model_selection import train_test_split, cross_val_score, StratifiedKFold\nfrom sklearn.linear_model import LogisticRegression\nfrom sklearn.ensemble import RandomForestClassifier\nfrom sklearn.neural_network import MLPClassifier\nfrom sklearn.preprocessing import StandardScaler\nfrom sklearn.pipeline import make_pipeline\nfrom sklearn.metrics import accuracy_score, precision_score, recall_score, f1_score, roc_auc_score, confusion_matrix\nfrom xgboost import XGBClassifier\n\nfwd_cols = ["Frequency", "Monetary", "Tenure", "AvgOrderValue", "Frequency_log", "Monetary_log", "Freq_Monetary_Interaction", "Recency"]\n\n\ndef build_forward(cutoff_date, horizon_days=90):\n    """Features from transactions up to cutoff_date; Churned = no purchase in the next horizon_days."""\n    past = data[data["InvoiceDate"] <= cutoff_date].copy()\n    future = data[(data["InvoiceDate"] > cutoff_date) & (data["InvoiceDate"] <= cutoff_date + pd.Timedelta(days=horizon_days))]\n    past["Amount"] = past["Quantity"] * past["Price"]\n    t = past.groupby("Customer ID").agg(\n        Frequency=("Invoice", "nunique"), Monetary=("Amount", "sum"),\n        first_purchase=("InvoiceDate", "min"), last_purchase=("InvoiceDate", "max"),\n    )\n    t["Tenure"] = (t["last_purchase"] - t["first_purchase"]).dt.days\n    t["Recency"] = (cutoff_date - t["last_purchase"]).dt.days  # measured at the cutoff, so it is known at prediction time\n    t["AvgOrderValue"] = t["Monetary"] / t["Frequency"]\n    t["Frequency_log"] = np.log1p(t["Frequency"])\n    t["Monetary_log"] = np.log1p(t["Monetary"].clip(lower=0))\n    t["Freq_Monetary_Interaction"] = t["Frequency"] * t["Monetary"]\n    t["Churned"] = (~t.index.isin(future["Customer ID"].unique())).astype(int)\n    return t\n\n\ncutoff_late = data["InvoiceDate"].max() - pd.Timedelta(days=90)\ncutoff_early = cutoff_late - pd.Timedelta(days=90)\nlate, early = build_forward(cutoff_late), build_forward(cutoff_early)\n\nprint("Data covers", data["InvoiceDate"].min().date(), "to", data["InvoiceDate"].max().date())\nprint("Cutoff date:", cutoff_late.date(), "| features use everything before it, the label is the 90 days after it")\nprint("Customers who bought before the cutoff:", len(late))\nprint("Stopped buying in the next 90 days:", int(late["Churned"].sum()), f"({late[\'Churned\'].mean() * 100:.1f}%)")', 'c2': 'def make_models():\n    return {\n        "Logistic Regression": make_pipeline(StandardScaler(), LogisticRegression(max_iter=1000, random_state=42)),\n        "XGBoost": XGBClassifier(n_estimators=100, max_depth=4, learning_rate=0.1, random_state=42),\n        "Neural Network (MLP)": make_pipeline(StandardScaler(), MLPClassifier(hidden_layer_sizes=(32, 16), max_iter=1000, random_state=42)),\n        "Random Forest": RandomForestClassifier(n_estimators=100, max_depth=6, random_state=42),\n    }\n\n\ndef show(name, y_true, model, X):\n    p = model.predict(X)\n    print(\n        f"{name:22} Accuracy {accuracy_score(y_true, p):.3f} | Precision {precision_score(y_true, p):.3f} | "\n        f"Recall {recall_score(y_true, p):.3f} | F1 {f1_score(y_true, p):.3f} | AUC {roc_auc_score(y_true, model.predict_proba(X)[:, 1]):.3f}"\n    )\n\n\nXa_train, Xa_test, ya_train, ya_test = train_test_split(late[fwd_cols], late["Churned"], test_size=0.2, random_state=42, stratify=late["Churned"])\nprint("Train customers:", len(Xa_train), "| Test customers:", len(Xa_test))\nfitted = {}\nfor name, model in make_models().items():\n    fitted[name] = model.fit(Xa_train, ya_train)\n    show(name, ya_test, fitted[name], Xa_test)\n\nno_recency = [c for c in fwd_cols if c != "Recency"]\nrf_no_recency = RandomForestClassifier(n_estimators=100, max_depth=6, random_state=42).fit(Xa_train[no_recency], ya_train)\nshow("RF without Recency", ya_test, rf_no_recency, Xa_test[no_recency])\nprint(f"Always-predict-churn baseline accuracy: {ya_test.mean():.3f}")', 'c3': '# Overfitting check for the chosen model\nrf_a = fitted["Random Forest"]\nprint(f"Random Forest train accuracy {accuracy_score(ya_train, rf_a.predict(Xa_train)):.3f} vs test accuracy {accuracy_score(ya_test, rf_a.predict(Xa_test)):.3f}")\ncv_auc = cross_val_score(RandomForestClassifier(n_estimators=100, max_depth=6, random_state=42), late[fwd_cols], late["Churned"],\n                         cv=StratifiedKFold(5, shuffle=True, random_state=0), scoring="roc_auc")\nprint(f"5-fold cross-validated AUC: mean {cv_auc.mean():.3f} (min {cv_auc.min():.3f}, max {cv_auc.max():.3f})")\n\n# Strictest test: train at the earlier cutoff, test on every customer at the later cutoff\nprint("\\nOut-of-time test: train at cutoff", cutoff_early.date(), "-> test on all", len(late), "customers at cutoff", cutoff_late.date())\nprint(f"Churn rate in the training window {early[\'Churned\'].mean():.3f} vs the test window {late[\'Churned\'].mean():.3f}")\nfor name, model in make_models().items():\n    show(name, late["Churned"], model.fit(early[fwd_cols], early["Churned"]), late[fwd_cols])\nrule = (late["Recency"] > 90).astype(int)\nprint(f"{\'Rule: Recency > 90d\':22} Accuracy {accuracy_score(late[\'Churned\'], rule):.3f} | Recall {recall_score(late[\'Churned\'], rule):.3f} | F1 {f1_score(late[\'Churned\'], rule):.3f}")', 'c4': '# A) Customer counts on the 1,052 held-out customers (Random Forest from the comparison above)\ntn, fp, fn, tp = confusion_matrix(ya_test, fitted["Random Forest"].predict(Xa_test)).ravel()\nprint(f"A) Test customers: {len(ya_test)} | really stopped buying: {tp + fn} | kept buying: {tn + fp}")\nprint(f"   Flagged by the model: {tp + fp} -> correct {tp}, false alarms {fp} | churners missed: {fn}")\nrule_pred = (Xa_test["Recency"] > 90).astype(int)\ntn2, fp2, fn2, tp2 = confusion_matrix(ya_test, rule_pred).ravel()\nprint(f"   Simple rule (Recency > 90d) flagged: {tp2 + fp2} -> correct {tp2}, false alarms {fp2} | churners missed: {fn2}")\n\n# B) Ranking by risk, using the out-of-time model (trained at the earlier cutoff, scored at the later one)\nrf_oot = RandomForestClassifier(n_estimators=100, max_depth=6, random_state=42).fit(early[fwd_cols], early["Churned"])\nscored = late.copy()\nscored["risk"] = rf_oot.predict_proba(late[fwd_cols])[:, 1]\nlast_year = data[(data["InvoiceDate"] <= cutoff_late) & (data["InvoiceDate"] > cutoff_late - pd.Timedelta(days=365))]\nscored["spend_12m"] = (last_year["Quantity"] * last_year["Price"]).groupby(last_year["Customer ID"]).sum().reindex(scored.index).fillna(0)\nscored["risk_group"] = pd.qcut(scored["risk"].rank(method="first"), 5, labels=["Safest 20%", "Low", "Middle", "High", "Riskiest 20%"])\ntotal_spend = scored["spend_12m"].sum()\nprint("\\nB) All", len(scored), "customers ranked by predicted risk (out-of-time model)")\nfor group, g in scored.groupby("risk_group", observed=True):\n    print(f"   {group:13} customers {len(g):5} | stopped buying {g[\'Churned\'].mean() * 100:5.1f}% | spend in the prior 12 months {g[\'spend_12m\'].sum():12,.0f} ({g[\'spend_12m\'].sum() / total_spend * 100:4.1f}% of total)")\n\n# C) High-value customers: top 25% by spend in the prior 12 months\nhigh_value = scored[scored["spend_12m"] >= scored["spend_12m"].quantile(0.75)].sort_values("risk", ascending=False)\nk = len(high_value) // 5\nprint(f"\\nC) High-value customers (top 25% by prior-12-month spend): {len(high_value)}, {high_value[\'spend_12m\'].sum() / total_spend * 100:.1f}% of spend, {high_value[\'Churned\'].mean() * 100:.1f}% stopped buying")\nprint(f"   Riskiest 20% of them: {k} customers | stopped buying {high_value[\'Churned\'].iloc[:k].mean() * 100:.1f}% ({int(high_value[\'Churned\'].iloc[:k].sum())} customers) | prior-12-month spend {high_value[\'spend_12m\'].iloc[:k].sum():,.0f}")\nprint(f"   Safest 20% of them:   {k} customers | stopped buying {high_value[\'Churned\'].iloc[-k:].mean() * 100:.1f}%")'}
OUT = {'c1': 'Data covers 2009-12-01 to 2011-12-09\nCutoff date: 2011-09-10 | features use everything before it, the label is the 90 days after it\nCustomers who bought before the cutoff: 5258\nStopped buying in the next 90 days: 2968 (56.4%)\n', 'c2': 'Train customers: 4206 | Test customers: 1052\nLogistic Regression    Accuracy 0.740 | Precision 0.753 | Recall 0.801 | F1 0.777 | AUC 0.809\nXGBoost                Accuracy 0.756 | Precision 0.755 | Recall 0.840 | F1 0.795 | AUC 0.819\nNeural Network (MLP)   Accuracy 0.750 | Precision 0.750 | Recall 0.837 | F1 0.791 | AUC 0.816\nRandom Forest          Accuracy 0.762 | Precision 0.756 | Recall 0.855 | F1 0.803 | AUC 0.818\nRF without Recency     Accuracy 0.721 | Precision 0.710 | Recall 0.854 | F1 0.775 | AUC 0.764\nAlways-predict-churn baseline accuracy: 0.565\n', 'c3': 'Random Forest train accuracy 0.766 vs test accuracy 0.762\n5-fold cross-validated AUC: mean 0.797 (min 0.793, max 0.802)\n\nOut-of-time test: train at cutoff 2011-06-12 -> test on all 5258 customers at cutoff 2011-09-10\nChurn rate in the training window 0.678 vs the test window 0.564\nLogistic Regression    Accuracy 0.711 | Precision 0.679 | Recall 0.927 | F1 0.784 | AUC 0.797\nXGBoost                Accuracy 0.703 | Precision 0.673 | Recall 0.919 | F1 0.777 | AUC 0.791\nNeural Network (MLP)   Accuracy 0.706 | Precision 0.674 | Recall 0.926 | F1 0.780 | AUC 0.796\nRandom Forest          Accuracy 0.700 | Precision 0.666 | Recall 0.939 | F1 0.779 | AUC 0.791\nRule: Recency > 90d    Accuracy 0.703 | Recall 0.802 | F1 0.753\n', 'c4': 'A) Test customers: 1052 | really stopped buying: 594 | kept buying: 458\n   Flagged by the model: 672 -> correct 508, false alarms 164 | churners missed: 86\n   Simple rule (Recency > 90d) flagged: 685 -> correct 494, false alarms 191 | churners missed: 100\n\nB) All 5258 customers ranked by predicted risk (out-of-time model)\n   Safest 20%    customers  1052 | stopped buying  16.5% | spend in the prior 12 months    6,005,182 (70.2% of total)\n   Low           customers  1051 | stopped buying  41.8% | spend in the prior 12 months    1,257,953 (14.7% of total)\n   Middle        customers  1052 | stopped buying  63.2% | spend in the prior 12 months      803,353 ( 9.4% of total)\n   High          customers  1051 | stopped buying  74.9% | spend in the prior 12 months      380,261 ( 4.4% of total)\n   Riskiest 20%  customers  1052 | stopped buying  85.8% | spend in the prior 12 months      103,026 ( 1.2% of total)\n\nC) High-value customers (top 25% by prior-12-month spend): 1315, 82.6% of spend, 21.1% stopped buying\n   Riskiest 20% of them: 263 customers | stopped buying 46.4% (122 customers) | prior-12-month spend 853,812\n   Safest 20% of them:   263 customers | stopped buying 4.6%\n'}
MD = {'m1': '## Step 2: The Prediction Problem (Forward-Looking Design)\n\n**Business question:** which customers will stop buying in the next 90 days, so the business can reach them before they leave?\n\n**Design:** pick a cutoff date 90 days before the data ends (2011-09-10). Every feature is built only from transactions **before** the cutoff. The label comes only from **after** it: Churned = no purchase in the following 90 days. This mirrors real use, where the model only knows the past.\n\n**Features (8):** Frequency (orders), Monetary (spend), Tenure, AvgOrderValue, log of Frequency and Monetary, Frequency x Monetary, and Recency (days since the last purchase, measured at the cutoff). Recency is a fair feature here because it is known on the day of prediction and the label comes entirely from later dates.', 'm2': '## Step 3: Model Comparison\n\nFour algorithms, same features, same split (4,206 customers to train, 1,052 held out to test).\n\n| Model | Accuracy | Recall | F1 | AUC |\n|---|---|---|---|---|\n| Logistic Regression | 74.0% | 80.1% | 0.777 | 0.809 |\n| XGBoost | 75.6% | 84.0% | 0.795 | 0.819 |\n| Neural Network (MLP) | 75.0% | 83.7% | 0.791 | 0.816 |\n| **Random Forest (chosen)** | **76.2%** | **85.5%** | **0.803** | 0.818 |\n\n**Random Forest is best on accuracy, recall and F1.** All four are close, so the features matter more than the algorithm. Without Recency the same Random Forest drops to 72.1% accuracy and 0.764 AUC, so Recency is the strongest signal. Always predicting churn would score 56.5%.', 'm3': '## Step 4: Is the Result Real? Overfitting Check and Out-of-Time Test\n\n**Overfitting check:** train accuracy 76.6% vs test accuracy 76.2%, so the model is not memorising. 5-fold cross-validated AUC is 0.797 (0.793 to 0.802), so **about 0.80 is the honest AUC**; the 0.818 above is one slightly favourable split.\n\n**Out-of-time test (strictest):** train at an earlier cutoff (2011-06-12), test on all 5,258 customers at the later cutoff (2011-09-10). AUC holds at 0.79 to 0.80 for every model, so the ranking of customers by risk is stable over time. Accuracy drops to about 70%, level with the simple rule "no purchase in 90 days" (70.3%), because churn is seasonal: 67.8% of customers went quiet in the summer training window vs 56.4% before Christmas, so a model trained on summer flags too many customers in autumn.\n\n**Takeaway:** the model is reliable for **ranking customers by churn risk (AUC about 0.80)**. The yes/no cut-off should be reset per season.', 'm4': "## Step 5: The Result in Numbers of Customers\n\n**On the 1,052 held-out customers:** 594 really stopped buying. The model flagged 672 customers: 508 correctly (it caught 85.5% of churners) with 164 false alarms, and missed 86. The simple rule caught 494 with 191 false alarms, so the model finds 14 more churners with 27 fewer false alarms.\n\n**Ranking all 5,258 customers by risk (out-of-time model):**\n\n| Risk group | Customers | Stopped buying | Share of prior-year spend |\n|---|---|---|---|\n| Riskiest 20% | 1,052 | 85.8% | 1.2% |\n| High | 1,051 | 74.9% | 4.4% |\n| Middle | 1,052 | 63.2% | 9.4% |\n| Low | 1,051 | 41.8% | 14.7% |\n| Safest 20% | 1,052 | 16.5% | 70.2% |\n\nThe ranking works (86% vs 17%), but the riskiest group spends very little, so it is not where the money is.\n\n**Where the model is valuable: high-value customers.** The top 25% of customers by prior-year spend (1,315 customers) bring in 82.6% of revenue, and 21.1% of them stopped buying. Within that group, the model's riskiest 20% (263 customers) stopped buying 46.4% of the time, against 4.6% for its safest 20%. Those 263 customers spent about £854K in the prior year, which makes them the group worth contacting first.", 'm5': '## Appendix: My First Approach (Snapshot Model)\n\nEverything below is the first version of this project, kept to show how I got to the design above. Here the churn label (no purchase in the last 90 days) and the features come from the same two-year window, so it identifies customers who have *already* gone quiet rather than predicting who *will*. Recency is excluded because the label was built from it. This limitation is why the forward-looking design above is the main result. The MLflow tracking, the API and the live app at the end still use this snapshot Random Forest.'}
def code_cell(key, cid): return {"cell_type": "code", "execution_count": None, "id": cid, "metadata": {}, "outputs": [{"name": "stdout", "output_type": "stream", "text": OUT[key].splitlines(True)}], "source": L(CODE[key])}
def md_cell(key, cid): return {"cell_type": "markdown", "id": cid, "metadata": {}, "source": L(MD[key])}
new = [md_cell("m1", "fwd-problem-md"), code_cell("c1", "fwd-build-code"), md_cell("m2", "fwd-compare-md"), code_cell("c2", "fwd-compare-code"),
       md_cell("m3", "fwd-checks-md"), code_cell("c3", "fwd-checks-code"), md_cell("m4", "fwd-customers-md"), code_cell("c4", "fwd-customers-code"), md_cell("m5", "snapshot-appendix-md")]
import re
for c in old:                                   # appendix headings must not clash with the main Step 2-5 headings
    if c["cell_type"] == "markdown":
        c["source"] = L(re.sub(r"(?m)^## [Ss]tep (\d+)", r"### Snapshot step \1", src(c)))
nb["cells"] = cells[:k] + new + old
json.dump(nb, open("churn.ipynb", "w"), indent=1, ensure_ascii=False); open("churn.ipynb", "a").write("\n")

r = open("README.md").read()
def part(a, b): return r[r.index(a):r.index(b)]
head = part("# Customer Churn Prediction", "## Where the data comes from")
data_sec = part("## Where the data comes from", "## How I defined churn").replace("The full dataset covers about 804,000 transactions across roughly 5,855 customers.", "The full dataset covers about 804,000 transactions across roughly 5,855 customers, over two years from December 2009 to December 2011.")
assert "over two years" in data_sec, "data sentence not found"
churn_def = part("## How I defined churn", "## Features and a leakage mistake I avoided").replace("## How I defined churn", "### How I defined churn in the snapshot version")
feats = part("## Features and a leakage mistake I avoided", "## Model comparison").replace("## Features and a leakage mistake I avoided", "### Features and a leakage mistake I avoided")
end_cmp = "## Forward looking validation" if "## Forward looking validation" in r else "## Experiment tracking"
compare = part("## Model comparison", end_cmp).replace("## Model comparison", "### Snapshot model comparison")
rest = part("## Experiment tracking", "## What I'd do differently with more time")
tail = r[r.index("## Files in this repository"):].replace("training and comparing all six models.", "training and comparing the models. The forward looking model comes first and the snapshot version is in the appendix.")
open("README.md", "w").write(head + data_sec + "## The main result, predicting who will stop buying\n\nA business does not need to know who has already gone quiet, it needs to know who is about to. So the main model in this project is forward looking. I picked a cutoff date, 10 September 2011, which is 90 days before the data ends. Every feature is built only from what happened before that date, and churn means the customer made no purchase in the 90 days after it. That gave me 5,258 customers who had bought at least once before the cutoff, and 56.4 percent of them did not buy again in the next 90 days.\n\nThe features are the number of orders, total spend, tenure, average order value, log versions of orders and spend, orders multiplied by spend, and Recency, which is the number of days since the last purchase as of the cutoff date. Recency is a fair feature here because it is measured before the cutoff and the label comes entirely from after it.\n\n## Model comparison\n\n**I compared four algorithms on the same split, 4,206 customers to train and 1,052 held out to test.**\n\n| Model | Accuracy | Recall | F1 score | AUC |\n|---|---|---|---|---|\n| Logistic Regression | 74.0% | 80.1% | 0.777 | 0.809 |\n| XGBoost | 75.6% | 84.0% | 0.795 | 0.819 |\n| Neural Network (MLP) | 75.0% | 83.7% | 0.791 | 0.816 |\n| **Random Forest (chosen)** | **76.2%** | **85.5%** | **0.803** | 0.818 |\n\n**Random Forest was best on accuracy, recall and F1.** All four models are close, which told me the features matter more than the choice of algorithm. Without Recency the same Random Forest drops to 72.1 percent accuracy, so Recency is the strongest signal. Always predicting churn would score 56.5 percent.\n\n## What the result means in customers\n\nOf the 1,052 held out customers, 594 really stopped buying. The model flagged 672 customers. 508 of those were correct, so it caught 85.5 percent of the customers who left, with 164 false alarms and 86 missed. A simple rule that flags anyone with no purchase in 90 days caught 494 with 191 false alarms, so the model finds 14 more churners with 27 fewer false alarms. That is a real but modest gain.\n\nThe model is more useful for ranking customers by risk than for a yes or no answer. I ranked all 5,258 customers using a model trained on an earlier period.\n\n| Risk group | Customers | Stopped buying | Share of prior year spend |\n|---|---|---|---|\n| Riskiest 20% | 1,052 | 85.8% | 1.2% |\n| High | 1,051 | 74.9% | 4.4% |\n| Middle | 1,052 | 63.2% | 9.4% |\n| Low | 1,051 | 41.8% | 14.7% |\n| Safest 20% | 1,052 | 16.5% | 70.2% |\n\nThe ranking works, 86 percent of the riskiest group left against 17 percent of the safest. But the riskiest group spends very little, so it is not where the money is.\n\n**The model is most valuable among high value customers.** The top 25 percent of customers by spend, 1,315 customers, bring in 82.6 percent of revenue, and 21.1 percent of them stopped buying. Within that group the model's riskiest 20 percent, 263 customers, stopped buying 46.4 percent of the time, against 4.6 percent for its safest 20 percent. Those 263 customers spent about 854 thousand pounds in the prior year, which makes them the group worth contacting first.\n\n## Checking that the result is real\n\nI checked for overfitting. Random Forest scored 76.6 percent accuracy on the training customers and 76.2 percent on the held out customers, so it is not memorising. Five fold cross validation gave an AUC of 0.797, between 0.793 and 0.802 on every fold, so about 0.80 is the honest AUC and the 0.818 in the table is one slightly favourable split.\n\nI also ran a stricter test. I trained the models at an earlier cutoff, 12 June 2011, and tested them on all 5,258 customers at the later cutoff, 10 September 2011.\n\n| Model | Accuracy | Recall | Precision | AUC |\n|---|---|---|---|---|\n| Logistic Regression | 71.1% | 92.7% | 67.9% | 0.797 |\n| XGBoost | 70.3% | 91.9% | 67.3% | 0.791 |\n| Neural Network (MLP) | 70.6% | 92.6% | 67.4% | 0.796 |\n| Random Forest | 70.0% | 93.9% | 66.6% | 0.791 |\n| Simple rule, no purchase in 90 days | 70.3% | 80.2% | | |\n\n**The AUC holds at about 0.79 to 0.80, so the ranking of customers by churn risk is stable over time.** Accuracy drops to about 70 percent, level with the simple rule, and the reason is seasonality. In the summer training window 67.8 percent of customers went quiet, but in the window before Christmas only 56.4 percent did, so a model trained on summer flags too many customers in autumn. The honest conclusion is that this model is useful for ranking customers by risk, with an AUC of about 0.80, and that the cut off for calling someone churned needs to be reset for the season.\n\n" + '## My first approach, a snapshot model\n\nBefore the forward looking model I built a simpler snapshot version, and I am keeping it here because it shows how I got to the final design. In the snapshot version the churn label and the features both come from the same two year window, so it identifies customers who have already gone quiet rather than predicting who will. That limitation is the reason I moved to the forward looking design above. The experiment tracking, the API and the live app described below still use this snapshot model.\n\n' + churn_def + feats + compare + rest + "## What I'd do differently with more time\n\nThe first thing I would do is move the live app and the API from the snapshot model to the forward looking model, so the deployed version answers the real business question. I would also train on several cutoff dates across the year and add seasonal features, since the strictest test showed that churn rates change a lot between summer and the weeks before Christmas. After that I would test whether features like product categories or country give the more complex models a real advantage, and I would connect the deployed app to the MLflow tracked model files instead of retraining at startup, since that is closer to how a real production system works.\n\n" + tail)
print("DONE: forward-looking model is now the main comparison in churn.ipynb and README.md")
